INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261119-senate-permitting-cloture', 'senate-permitting-bill-cloture-65-31-capito-substitute-adopted-69-27', 'newsroom', 'news_story', 'congress', 'EDITORIAL_REVIEW', 0, 'Senate adopts the bipartisan permitting and power-grid rewrite 69-27 and limits debate on the bill 65-31', 'Three roll calls on Wednesday, Nov. 18, put the Bipartisan American Affordability and Jobs Act on track for final passage. Republicans Josh Hawley and Mike Rounds voted no on the last one.', 'The Senate moved the Bipartisan American Affordability and Jobs Act close to final passage on Wednesday, Nov. 18, with three roll-call votes on H.R. 2347, the House bill used as its vehicle, according to the Senate Daily Press Gallery''s floor log.

## The three votes

At 12:41 p.m., senators voted 70-26 to waive a budget point of order raised by Sen. Jeff Merkley (D-Ore.) against the substitute amendment from Sen. Shelley Moore Capito (R-W.Va.). At 1:23 p.m., they adopted that substitute, 69-27. At 2:30 p.m., they voted 65-31 to limit debate on the bill itself, clearing the 60-vote threshold. The floor log did not record a final passage vote on Wednesday.

Republicans Josh Hawley of Missouri and Mike Rounds of South Dakota voted no on the last vote, The Hill reported. Rounds objected to the bill''s power-line provisions. The 31 no votes included 29 Democrats and senators who caucus with them.

## What the bill would do

The bill aims to speed permits and environmental reviews for energy and infrastructure projects, The Hill reported. It would let federal regulators approve power lines when states do not act, bar presidents from revoking energy permits already granted, require lawsuits to be filed within 150 days of a project''s approval and make large data centers pay costs tied to their electricity demand.

The White House, major unions and energy and manufacturing groups back it. Several environmental groups and tribes oppose it. The Hill described Senate passage as highly likely but said the House path is less certain: House Energy and Commerce Chairman Brett Guthrie (R-Ky.) wants changes, and the bill competes with a crowded lame-duck agenda that includes a possible funding lapse in December.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Sheldon_Whitehouse,_official_portrait,_116th_congress.jpg/1280px-Sheldon_Whitehouse,_official_portrait,_116th_congress.jpg', 'Sen. Sheldon Whitehouse, D-R.I., a co-author of the permitting bill (file). Official U.S. Senate portrait via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-19.sql', 8, 0, 'newsroom-assistant', '2026-11-19T10:55:00.000Z', '2026-11-19T10:55:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261119-senate-permitting-cloture-src1', 'bd-20261119-senate-permitting-cloture', 'Wednesday, November 18, 2026 (Senate floor log)', 'https://www.dailypress.senate.gov/wednesday-november-18-2026/', 'U.S. Senate Daily Press Gallery', 'web', 'PRIMARY_SOURCE', 1, 1, '2026-11-19T10:55:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-19. Editor to confirm.', 'newsroom-assistant', '2026-11-19T10:55:00.000Z');
