INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261119-peltola-alaska-senate', 'peltola-wins-alaska-senate-seat-defeats-dan-sullivan-democrats-56-44', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Mary Peltola unseats Sen. Dan Sullivan in Alaska, giving Democrats a 56-44 Senate majority in January', 'The Associated Press called the last undecided Senate race of the midterms on Tuesday, Nov. 17. Peltola cleared 50% of the vote, so no ranked-choice count was needed.', 'Democrat Mary Peltola defeated two-term Republican Sen. Dan Sullivan in Alaska, the Associated Press projected on the evening of Tuesday, Nov. 17, Alaska''s News Source reported. It was the last Senate race of the 2026 midterms to be decided.

## The count

In the latest tally, Peltola had 144,302 votes to Sullivan''s 131,844, a lead of 12,458, according to Alaska''s News Source. Her share, 50.12%, put her just over the majority needed to win outright, so the state did not need to run a ranked-choice tabulation. Sullivan''s campaign had said it would not comment until all ballots were counted.

## What it means for the Senate

Democrats will hold 56 seats to Republicans'' 44 when the new Congress meets in January, after flipping nine Republican-held seats, PBS NewsHour reported, citing the AP. Alaska''s News Source called it the party''s biggest midterm gain in nearly 70 years.

Peltola, the first Alaska Native elected to Congress, previously held the state''s only House seat and lost it in 2024 to Republican Nick Begich. She will be the fifth Democrat to represent Alaska in the Senate since statehood, according to PBS.

## A contested race

The race drew a federal lawsuit. The Justice Department sued to block certification if the incumbent lost, citing possible voter confusion with a third candidate, retired teacher Dan J. Sullivan. A judge dismissed the suit and the department appealed, PBS reported. Peltola and Dan J. Sullivan have both denied reports that her campaign helped recruit him.

Alaskans also elected Democrat Jonathan Kreiss-Tomkins governor. The state''s House race between Begich and independent Bill Hill had not been called.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Mary_Peltola_Congressional_Member_Portrait_(2).jpeg/1280px-Mary_Peltola_Congressional_Member_Portrait_(2).jpeg', 'Mary Peltola in her official portrait as a member of the U.S. House (file). U.S. House photo via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-19.sql', 8, 0, 'newsroom-assistant', '2026-11-19T10:55:00.000Z', '2026-11-19T10:55:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261119-peltola-alaska-senate-src1', 'bd-20261119-peltola-alaska-senate', 'AP calls it: Peltola wins Alaska''s US Senate seat over GOP incumbent Sullivan', 'https://www.alaskasnewssource.com/2026/11/18/peltola-is-going-back-dc-after-ap-calls-last-senate-race-democratic-challenger/', 'Alaska''s News Source', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-19T10:55:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-19. Editor to confirm.', 'newsroom-assistant', '2026-11-19T10:55:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261119-peltola-alaska-senate-src2', 'bd-20261119-peltola-alaska-senate', 'Democrat Mary Peltola wins Alaska Senate seat, beating Republican incumbent Dan Sullivan', 'https://www.pbs.org/newshour/politics/democrat-mary-peltola-wins-alaska-senate-seat-beating-republican-incumbent-dan-sullivan', 'PBS NewsHour (AP)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-19T10:55:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-19. Editor to confirm.', 'newsroom-assistant', '2026-11-19T10:55:00.000Z');
