INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261119-iran-gulf-attacks', 'iran-targets-ali-al-salem-kuwait-bahrain-after-us-strike-qeshm-island', 'newsroom', 'news_story', 'policy', 'EDITORIAL_REVIEW', 0, 'Iran fires on a U.S.-used air base in Kuwait and on Bahrain after a U.S. jet strikes a Revolutionary Guard site', 'Kuwait and Bahrain said their air defenses intercepted the attacks early on Wednesday, Nov. 18. Secretary of State Marco Rubio said he saw no imminent threat to Washington.', 'Iran widened its attacks on Gulf states early on Wednesday, Nov. 18, targeting Ali Al Salem Air Base in Kuwait and sites in Bahrain, The Associated Press reported. It was the first such wave after about two months without attacks of this kind.

## The attacks

Iran''s state broadcaster said its forces fired at air defense systems and drone and missile launch platforms at Ali Al Salem, which hosts U.S. forces. Kuwait''s military said it intercepted drones and reported no immediate damage. In Bahrain, home to the U.S. Navy''s 5th Fleet, the Interior Ministry issued two shelter alerts, and the military said it intercepted a number of Iranian attacks without giving details on damage, according to the AP. No casualties were reported in either country.

## What came before

On Tuesday, Nov. 17, Iran attacked a U.S. radar installation in Bahrain, and a U.S. fighter jet struck a Revolutionary Guard missile launch site on Qeshm Island in the Strait of Hormuz in response, the AP reported. The UAE state oil company ADNOC said one crew member was missing and 11 were injured after a tanker it owns was hit in the strait.

## Washington''s response

The U.S. military did not immediately comment. President Trump has said new strikes are highly unlikely while sending a third aircraft carrier and thousands more troops to the region, the AP reported. Secretary of State Marco Rubio said he saw no imminent threat to Washington after a CNN report on Iranian planning against U.S. officials, according to The Times of Israel''s live coverage. The war began on Feb. 28, when Israel and the United States attacked Iran.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/NAVAL_SUPPORT_ACTIVITY_BAHRAIN_150112-N-KM734-021_(15655897534).jpg/1280px-NAVAL_SUPPORT_ACTIVITY_BAHRAIN_150112-N-KM734-021_(15655897534).jpg', 'Naval Support Activity Bahrain, home of the U.S. Navy''s 5th Fleet, in January 2015 (file). U.S. Navy photo via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-19.sql', 8, 0, 'newsroom-assistant', '2026-11-19T10:55:00.000Z', '2026-11-19T10:55:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261119-iran-gulf-attacks-src1', 'bd-20261119-iran-gulf-attacks', 'Iran widens Gulf attacks by targeting U.S. air base in Kuwait, sites in Bahrain', 'https://spectrumlocalnews.com/tx/austin/international/2026/11/18/u-s--iran-war-gulf-attacks-kuwait-bahrain', 'The Associated Press (via Spectrum News)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-19T10:55:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-19. Editor to confirm.', 'newsroom-assistant', '2026-11-19T10:55:00.000Z');
