INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261119-chutkan-arch-order', 'chutkan-extends-order-blocking-trump-triumphal-arch-memorial-circle-dec-3', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Judge Chutkan keeps Trump''s 250-foot arch on hold for 14 more days, through Dec. 3', 'The order bars construction at Memorial Circle while the judge weighs a preliminary injunction. Washington, D.C., Virginia, veterans and members of the Kennedy family are suing.', 'U.S. District Judge Tanya Chutkan on Wednesday, Nov. 18, extended by 14 days her order blocking construction of the 250-foot memorial arch the Trump administration wants to build at Memorial Circle on Columbia Island in Washington, The Associated Press reported. Construction stays on hold until Thursday, Dec. 3, or until she rules on a request for a preliminary injunction, whichever comes first.

## Why the judge extended it

Chutkan first issued a temporary restraining order on Thursday, Nov. 5, shortly after the National Capital Planning Commission gave the project final approval by an 8-4 vote. She wrote that an extension was warranted because nothing had significantly changed in the case over the two weeks since, according to the AP.

## Who is suing

The original suit was brought by a group of Vietnam veterans and a retired architectural historian. The District of Columbia and Virginia sued on Saturday, Oct. 31, and Chutkan combined their case with the first. Members of the Kennedy family filed suit on Tuesday, Nov. 10, citing the arch''s effect on relatives buried at nearby Arlington National Cemetery. Another suit is pending in federal court in Virginia.

The challengers argue that the administration needs approval from Congress and that the arch would block sightlines between historic landmarks. The administration says Congress cleared the way for a monument at Memorial Circle decades ago.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/98/Traffic_plaza_on_Columbia_Island_-_Arlington_Memorial_Bridge_-_2011.jpg/1280px-Traffic_plaza_on_Columbia_Island_-_Arlington_Memorial_Bridge_-_2011.jpg', 'Memorial Circle on Columbia Island at the Virginia end of Arlington Memorial Bridge, 2011 (file). Photo via Wikimedia Commons (free license; editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-19.sql', 7, 0, 'newsroom-assistant', '2026-11-19T10:55:00.000Z', '2026-11-19T10:55:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261119-chutkan-arch-order-src1', 'bd-20261119-chutkan-arch-order', 'Judge issues 14-day extension of order blocking Trump''s memorial arch in DC', 'https://abcnews.com/US/wireStory/judge-issues-14-day-extension-order-blocking-trumps-138263827', 'The Associated Press (via ABC News)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-19T10:55:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-19. Editor to confirm.', 'newsroom-assistant', '2026-11-19T10:55:00.000Z');
INSERT OR IGNORE INTO story_events (id, story_id, from_status, to_status, actor, note, created_at) VALUES ('bd-20261119-chutkan-arch-order-ev1', 'bd-20261119-chutkan-arch-order', NULL, 'EDITORIAL_REVIEW', 'newsroom-assistant', 'Drafted from attributed reporting and primary sources; awaiting editor approval', '2026-11-19T10:55:00.000Z');
INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261119-bruins-red-wings', 'bruins-4-red-wings-1-pastrnak-zacha-tarasov-27-saves-snap-skid', 'newsroom', 'news_story', 'nhl', 'EDITORIAL_REVIEW', 0, 'Bruins 4, Red Wings 1: Boston scores four straight goals in Detroit to snap a three-game losing streak (Wed., Nov. 18)', 'JJ Peterka, Pavel Zacha, David Pastrnak and Casey Mittelstadt scored, and Daniil Tarasov made 27 saves at Little Caesars Arena.', 'The Bruins beat the Detroit Red Wings 4-1 at Little Caesars Arena on Wednesday, Nov. 18, ending a three-game losing streak, according to ESPN''s recap.

## How the goals came

Lucas Raymond gave Detroit a 1-0 lead at 16:58 of the first period. Boston answered in the second: JJ Peterka tied it at 2:47, and Pavel Zacha scored on the power play at 11:48 for his sixth goal of the season. David Pastrnak made it 3-1 at 5:11 of the third, and Casey Mittelstadt added an empty-net goal at 19:05.

Mason Lohrei and Morgan Geekie each had two assists. Daniil Tarasov made 27 saves for Boston.

## Where it leaves them

The Bruins are 14-7-1 with 29 points, second in the Atlantic Division, according to ESPN. Detroit fell to 8-11-3 and has lost six of its last seven. Boston plays the Washington Capitals on Saturday, Nov. 21.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Detroit_August_2025_07_(Little_Caesars_Arena).jpg/1280px-Detroit_August_2025_07_(Little_Caesars_Arena).jpg', 'Little Caesars Arena in Detroit, August 2025 (file). Photo via Wikimedia Commons (free license; editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-19.sql', 7, 0, 'newsroom-assistant', '2026-11-19T10:55:00.000Z', '2026-11-19T10:55:00.000Z');
