INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261119-nuggets-celtics', 'nuggets-105-celtics-101-jokic-murray-tatum-24-boston-second-straight-loss', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Nuggets 105, Celtics 101: Boston shoots 11-for-44 from three and drops a second straight game in Denver (Wed., Nov. 18)', 'Jayson Tatum scored 24 with eight rebounds but committed six turnovers. Nikola Jokic had 24 points and nine assists, and Jamal Murray added 21 with four steals.', 'The Denver Nuggets beat the Celtics 105-101 at Ball Arena on Wednesday, Nov. 18, according to the NBA''s box score and ESPN. It was Boston''s second loss in a row after Orlando ended its six-game winning streak at TD Garden on Monday, Nov. 16.

## The Celtics

Jayson Tatum led Boston with 24 points and eight rebounds on 10-of-22 shooting but turned the ball over six times. Neemias Queta had 17 points and 10 rebounds, Payton Pritchard scored 15, and Derrick White had 12 points and eight assists on 5-of-16 shooting. Paul George added 10 points.

The Celtics made 40 of 98 shots and only 11 of 44 three-point attempts, according to the box score.

## The Nuggets

Nikola Jokic scored 24 points with nine assists and eight rebounds. Jamal Murray had 21 points, seven rebounds, four steals and two blocks. DeMar DeRozan scored 18, Christian Braun 15 and Aaron Gordon 13 with eight rebounds.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Ball_Arena_exterior_2022.jpg/1280px-Ball_Arena_exterior_2022.jpg', 'Ball Arena, home of the Denver Nuggets, in 2022 (file). Photo via Wikimedia Commons (free license; editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-19.sql', 7, 0, 'newsroom-assistant', '2026-11-19T10:55:00.000Z', '2026-11-19T10:55:00.000Z');
