INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261119-patriots-byard-maye', 'kevin-byard-drake-maye-probably-out-rest-of-season-patriots-devito', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Patriots captain Kevin Byard says Drake Maye is probably out for the season as Tommy DeVito takes over', 'Byard spoke on WEEI on Tuesday, Nov. 17. New England is 5-5 and on its bye week, a game behind Cleveland for the AFC''s last wild-card spot.', 'Patriots safety and captain Kevin Byard said on WEEI on Tuesday, Nov. 17, that quarterback Drake Maye is probably going to miss the rest of the season, Yahoo Sports reported. Byard said the team has to rally around its backup quarterback.

## Maye''s status

Maye hurt his ankle on the Patriots'' first drive of their 35-10 loss to the Detroit Lions in Germany on Sunday, Nov. 15. ESPN has reported that the team fears a fracture. The Patriots have not given a timeline, but coach Mike Vrabel said Maye stayed in Germany for more tests and that he would not expect him back right after the bye, according to Yahoo Sports. NBC Sports Boston''s Phil Perry wrote on Wednesday, Nov. 18, that there is not a lot of optimism Maye returns this season.

## DeVito in charge

Tommy DeVito, who recently signed a new two-year contract, is the starter for now, NBC Sports Boston reported. Perry does not expect New England to sign a veteran such as Jimmy Garoppolo but would not be surprised by a depth signing.

The Patriots are 5-5 and on their bye week, one game behind the Cleveland Browns for the final AFC wild-card spot. Their next game is against the Los Angeles Chargers.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Gillette_Stadium04.jpg/1280px-Gillette_Stadium04.jpg', 'Gillette Stadium in Foxborough, home of the Patriots (file). Photo via Wikimedia Commons (free license; editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-19.sql', 6, 0, 'newsroom-assistant', '2026-11-19T10:55:00.000Z', '2026-11-19T10:55:00.000Z');
